import{_ as t,c as d,o as a,a5 as e}from"./chunks/framework.hc4fELLV.js";const r="/monitor/image/1.png",f=JSON.parse('{"title":"前端监控内容","description":"","frontmatter":{},"headers":[],"relativePath":"web/content.md","filePath":"web/content.md","lastUpdated":1722106831000}'),o={name:"web/content.md"},n=e('<h1 id="前端监控内容" tabindex="-1">前端监控内容 <a class="header-anchor" href="#前端监控内容" aria-label="Permalink to &quot;前端监控内容&quot;">​</a></h1><p>前端监控要监控哪些内容呢？目标主要有三类：</p><h2 id="错误监控" tabindex="-1">错误监控 <a class="header-anchor" href="#错误监控" aria-label="Permalink to &quot;错误监控&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误名称</th><th>备注</th></tr></thead><tbody><tr><td>JS错误</td><td>JS执行错误或者promise异常</td></tr><tr><td>资源异常</td><td>script、link等资源加载异常</td></tr><tr><td>接口错误</td><td>ajax或fetch请求接口异常</td></tr></tbody></table><h2 id="性能监控" tabindex="-1">性能监控 <a class="header-anchor" href="#性能监控" aria-label="Permalink to &quot;性能监控&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误名称</th><th>备注</th></tr></thead><tbody><tr><td>加载时间</td><td>各个阶段的加载时间</td></tr><tr><td>TTFB(time to first byte)(首字节时间)</td><td>是指浏览器发起第一个请求到数据返回第一个字节所消耗的时间，这个事件包含了网络请求时间、后端处理事件</td></tr><tr><td>FP(First Paint)(首次绘制)</td><td>首次绘制包括了任何用户自定义的背景绘制，它是将第一个像素点绘制到屏幕的时间</td></tr><tr><td>FCP(First Content Paint)(首次内容绘制)</td><td>首次内容绘制是浏览器将第一个DOM渲染到屏幕的时间，可以是任何文本、图像、SVG等的时间</td></tr><tr><td>FMP(First Meaningful paint)(首次有意义绘制)</td><td>首次有意义绘制是页面可用性的度量标准</td></tr><tr><td>FID(First Input Delay)(首次输入延迟)</td><td>用户首次和页面交互到页面响应交互的时间</td></tr><tr><td>卡顿</td><td>超过50ms的长任务</td></tr><tr><td>白屏</td><td>页面空白</td></tr></tbody></table><h2 id="行为监控" tabindex="-1">行为监控 <a class="header-anchor" href="#行为监控" aria-label="Permalink to &quot;行为监控&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误名称</th><th>备注</th></tr></thead><tbody><tr><td>PV</td><td>page view 即页面浏览量或点击量</td></tr><tr><td>UV</td><td>指访问某个站点的不同IP地址的人数</td></tr><tr><td>页面的停留时间</td><td>用户的每一个页面的停留时间</td></tr></tbody></table><p><img src="'+r+'" alt=""></p>',9),i=[n];function h(s,l,c,_,b,p){return a(),d("div",null,i)}const u=t(o,[["render",h]]);export{f as __pageData,u as default};
